#!/usr/bin/env bash
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/../lib/common.sh"
N="${1:-27}"; if (($#>0)); then shift; fi
[[ "$N" == 27 ]] || { echo 'Stage-R promotion targets n=27' >&2; exit 2; }
PROFILE_FILE="${PROFILE_FILE:-$ONEESAN_ROOT/work/b300_hbm_profile_refined21.env}"; STAGE_F_ENV="${STAGE_F_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_nextself_staged_winner.env}"
STAGEN_WINNER_ENV="${STAGEN_WINNER_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_pair_block_load_stagen_staged_g8_winner.env}"; STAGEN_PREPARE_ENV="${STAGEN_PREPARE_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_pair_block_load_stagen_fullprime_n27_prepared.env}"
STAGEO_PREPARE_ENV="${STAGEO_PREPARE_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stageo_cg_l2_fullprime_n27_prepared.env}"; STAGEP_PREPARE_ENV="${STAGEP_PREPARE_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stagep_mate_cg_l2_fullprime_n27_prepared.env}"
STAGEQ_WINNER_ENV="${STAGEQ_WINNER_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stageq_ilp8_count_cg_l2_staged_g8_winner.env}"; STAGEQ_PREPARE_ENV="${STAGEQ_PREPARE_ENV:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stageq_ilp8_count_cg_l2_fullprime_n27_prepared.env}"
ARCH="${ARCH:-native}"; MOD="${MOD:-4294967291}"; TARGET_MIB="${TARGET_MIB:-65536}"; MAX_WINDOW="${MAX_WINDOW:-14}"; NGPU="${NGPU:-8}"; UPSTREAM_KIND="${UPSTREAM_KIND:-auto}"
RUN_STAGED="${RUN_STAGED:-1}"; PREPARE_ONLY="${PREPARE_ONLY:-0}"; SELECT_ONLY="${SELECT_ONLY:-1}"; REBUILD_BUCKETS="${REBUILD_BUCKETS:-1}"; MIN_SPEEDUP="${MIN_SPEEDUP:-1.002}"; PAIR_POLICY_LIST="${PAIR_POLICY_LIST:-default cg cs}"; BLOCK_POLICY_LIST="${BLOCK_POLICY_LIST:-default cg cs}"
STAGED_PREFIX="${STAGED_PREFIX:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stager_ilp2_load_staged_g${NGPU}}"; WINNER_ENV="${WINNER_ENV:-${STAGED_PREFIX}_winner.env}"; MANIFEST="${MANIFEST:-${WINNER_ENV%.env}_promotion-inputs.sha256}"
RACE_PREFIX="${RACE_PREFIX:-$ONEESAN_ROOT/work/b300_nextgen_hybrid8_stager_ilp2_load_fullprime_n27}"; PREPARE_ENV="${PREPARE_ENV:-${RACE_PREFIX}_prepared.env}"; PROMOTION_ENV="${PROMOTION_ENV:-${RACE_PREFIX}_promotion.env}"
for x in RUN_STAGED PREPARE_ONLY SELECT_ONLY REBUILD_BUCKETS; do [[ "${!x}" == 0 || "${!x}" == 1 ]] || exit 2; done
[[ "$NGPU" =~ ^[1-8]$ ]] || exit 2; case "$UPSTREAM_KIND" in auto|stagen|stageo|stagep|stageq) ;; *) exit 2;; esac
for x in MOD TARGET_MIB MAX_WINDOW; do [[ "${!x}" =~ ^[1-9][0-9]*$ ]] || exit 2; done
python3 - "$MIN_SPEEDUP" <<'PY'
import sys
if float(sys.argv[1]) < 1.0: raise SystemExit('MIN_SPEEDUP must be >=1')
PY
for f in "$PROFILE_FILE" "$STAGE_F_ENV" "$STAGEN_WINNER_ENV" "$STAGEN_PREPARE_ENV"; do [[ -s "$f" ]] || { echo "missing Stage-R input=$f" >&2; exit 2; }; done
command -v sha256sum >/dev/null || exit 2
if [[ "$RUN_STAGED" == 1 ]]; then
  STAGE_F_ENV="$STAGE_F_ENV" STAGEN_WINNER_ENV="$STAGEN_WINNER_ENV" STAGEN_PREPARE_ENV="$STAGEN_PREPARE_ENV" STAGEO_PREPARE_ENV="$STAGEO_PREPARE_ENV" STAGEP_PREPARE_ENV="$STAGEP_PREPARE_ENV" STAGEQ_WINNER_ENV="$STAGEQ_WINNER_ENV" STAGEQ_PREPARE_ENV="$STAGEQ_PREPARE_ENV" \
    UPSTREAM_KIND="$UPSTREAM_KIND" ARCH="$ARCH" MOD="$MOD" TARGET_MIB="$TARGET_MIB" MAX_WINDOW="$MAX_WINDOW" NGPU="$NGPU" MIN_SPEEDUP="$MIN_SPEEDUP" PAIR_POLICY_LIST="$PAIR_POLICY_LIST" BLOCK_POLICY_LIST="$BLOCK_POLICY_LIST" PREFIX="$STAGED_PREFIX" FINAL_ENV="$WINNER_ENV" \
    bash "$ONEESAN_ROOT/scripts/bench/b300-nextgen-hybrid8-stager-ilp2-load-policy-staged-calibrate.sh"
fi
[[ -s "$WINNER_ENV" ]] || { echo "missing Stage-R winner=$WINNER_ENV" >&2; exit 3; }
# shellcheck disable=SC1090
source "$WINNER_ENV"
for k in B300_STAGER_STAGED_VALIDATED B300_STAGER_FINAL_ENABLED B300_STAGER_NGPU B300_STAGER_UPSTREAM_KIND B300_STAGER_UPSTREAM_PAIR_POLICY B300_STAGER_UPSTREAM_BLOCK_POLICY B300_STAGER_HIGH_PAIR_POLICY B300_STAGER_HIGH_BLOCK_POLICY B300_STAGER_HIGH_PAIR_L2_BYTES B300_STAGER_HIGH_BLOCK_L2_BYTES B300_STAGER_PAIR_POLICY B300_STAGER_BLOCK_POLICY B300_STAGER_FINAL_BIN B300_STAGER_FINAL_THREADS B300_STAGER_FINAL_SPEEDUP B300_STAGER_FINAL_SPILL_FREE B300_STAGER_CONTROL_BIN B300_STAGER_CONTROL_THREADS B300_STAGER_FINAL_STAGE_ROWS B300_STAGER_FINAL_STAGE_RESIDUE B300_STAGER_UPSTREAM_MANIFEST; do [[ -n "${!k+x}" ]] || { echo "Stage-R winner missing $k" >&2; exit 3; }; done
[[ "$B300_STAGER_STAGED_VALIDATED" == 1 && "$B300_STAGER_FINAL_ENABLED" == 1 && "$B300_STAGER_FINAL_SPILL_FREE" == 1 && "$B300_STAGER_NGPU" == "$NGPU" ]] || { echo 'Stage R did not survive staged validation' >&2; exit 4; }
[[ "$B300_STAGER_PAIR_POLICY" != "$B300_STAGER_UPSTREAM_PAIR_POLICY" || "$B300_STAGER_BLOCK_POLICY" != "$B300_STAGER_UPSTREAM_BLOCK_POLICY" ]] || { echo 'Stage R retained exact upstream ILP2 tuple' >&2; exit 4; }
python3 - "$B300_STAGER_FINAL_SPEEDUP" "$MIN_SPEEDUP" <<'PY'
import sys
if float(sys.argv[1]) < float(sys.argv[2]): raise SystemExit('Stage-R speedup below threshold')
PY
# Resolve and bind the exact prepared upstream selected by the staged winner.
UP_PREP=""; case "$B300_STAGER_UPSTREAM_KIND" in stagen) UP_PREP="$STAGEN_PREPARE_ENV";; stageo) UP_PREP="$STAGEO_PREPARE_ENV";; stagep) UP_PREP="$STAGEP_PREPARE_ENV";; stageq) UP_PREP="$STAGEQ_PREPARE_ENV";; *) exit 3;; esac
[[ -s "$UP_PREP" ]] || { echo "Stage-R upstream prepare missing=$UP_PREP" >&2; exit 3; }
# shellcheck disable=SC1090
source "$UP_PREP"
case "$B300_STAGER_UPSTREAM_KIND" in
  stagen) UP_BIN="$B300_STAGEN_PREPARED_BIN"; UP_THREADS="$B300_STAGEN_PREPARED_THREADS"; UP_MAN="$B300_STAGEN_PREPARED_MANIFEST";;
  stageo) UP_BIN="$B300_STAGEO_PREPARED_BIN"; UP_THREADS="$B300_STAGEO_PREPARED_THREADS"; UP_MAN="$B300_STAGEO_PREPARED_MANIFEST";;
  stagep) UP_BIN="$B300_STAGEP_PREPARED_BIN"; UP_THREADS="$B300_STAGEP_PREPARED_THREADS"; UP_MAN="$B300_STAGEP_PREPARED_MANIFEST";;
  stageq) UP_BIN="$B300_STAGEQ_PREPARED_BIN"; UP_THREADS="$B300_STAGEQ_PREPARED_THREADS"; UP_MAN="$B300_STAGEQ_PREPARED_MANIFEST";;
esac
[[ -x "$UP_BIN" && -s "$UP_MAN" ]] || exit 3; sha256sum -c "$UP_MAN" >/dev/null || { echo 'Stage-R upstream manifest failed' >&2; exit 3; }
[[ "$B300_STAGER_CONTROL_BIN" == "$UP_BIN" ]] || { echo 'Stage-R control is not exact prepared upstream binary' >&2; exit 3; }
[[ -x "$B300_STAGER_FINAL_BIN" ]] || exit 3
if [[ "$RUN_STAGED" == 1 ]]; then
  tmp="${MANIFEST}.tmp"; mkdir -p "$(dirname "$MANIFEST")"; files=("$WINNER_ENV" "$STAGE_F_ENV" "$STAGEN_WINNER_ENV" "$STAGEN_PREPARE_ENV" "$UP_PREP" "$UP_MAN" "$B300_STAGER_FINAL_BIN" "$B300_STAGER_CONTROL_BIN"); [[ -s "$STAGEQ_WINNER_ENV" ]] && files+=("$STAGEQ_WINNER_ENV"); sha256sum "${files[@]}" >"$tmp"; mv "$tmp" "$MANIFEST"
else [[ -s "$MANIFEST" ]] || { echo 'missing Stage-R promotion manifest' >&2; exit 3; }; fi
sha256sum -c "$MANIFEST" >/dev/null || { echo 'Stage-R promotion fingerprint mismatch' >&2; exit 3; }
FINAL_SHA="$(sha256sum "$B300_STAGER_FINAL_BIN"|awk '{print $1}')"; CONTROL_SHA="$(sha256sum "$B300_STAGER_CONTROL_BIN"|awk '{print $1}')"; MANIFEST_SHA="$(sha256sum "$MANIFEST"|awk '{print $1}')"
label="stager_ilp2_p${B300_STAGER_PAIR_POLICY}_b${B300_STAGER_BLOCK_POLICY}_up${B300_STAGER_UPSTREAM_KIND}"; control_label="stager_exact_${B300_STAGER_UPSTREAM_KIND}_control"
cat >"$PROMOTION_ENV" <<EOF
B300_STAGER_PROMOTION_VALIDATED=1
B300_STAGER_PROMOTION_MOD=$MOD
B300_STAGER_PROMOTION_NGPU=$NGPU
B300_STAGER_PROMOTION_UPSTREAM_KIND=$B300_STAGER_UPSTREAM_KIND
B300_STAGER_PROMOTION_PAIR_POLICY=$B300_STAGER_PAIR_POLICY
B300_STAGER_PROMOTION_BLOCK_POLICY=$B300_STAGER_BLOCK_POLICY
B300_STAGER_PROMOTION_BIN=$(printf '%q' "$B300_STAGER_FINAL_BIN")
B300_STAGER_PROMOTION_BIN_SHA256=$FINAL_SHA
B300_STAGER_PROMOTION_CONTROL_BIN=$(printf '%q' "$B300_STAGER_CONTROL_BIN")
B300_STAGER_PROMOTION_CONTROL_SHA256=$CONTROL_SHA
B300_STAGER_PROMOTION_SPEEDUP=$B300_STAGER_FINAL_SPEEDUP
B300_STAGER_PROMOTION_MANIFEST=$(printf '%q' "$MANIFEST")
B300_STAGER_PROMOTION_MANIFEST_SHA256=$MANIFEST_SHA
EOF
if [[ "$PREPARE_ONLY" == 1 ]]; then
  mkdir -p "$(dirname "$PREPARE_ENV")"; {
    printf 'B300_STAGER_PREPARED=1\n'; printf 'B300_STAGER_PREPARED_MOD=%q\n' "$MOD"; printf 'B300_STAGER_PREPARED_NGPU=%q\n' "$NGPU"; printf 'B300_STAGER_PREPARED_UPSTREAM_KIND=%q\n' "$B300_STAGER_UPSTREAM_KIND"
    printf 'B300_STAGER_PREPARED_UPSTREAM_PAIR_POLICY=%q\n' "$B300_STAGER_UPSTREAM_PAIR_POLICY"; printf 'B300_STAGER_PREPARED_UPSTREAM_BLOCK_POLICY=%q\n' "$B300_STAGER_UPSTREAM_BLOCK_POLICY"; printf 'B300_STAGER_PREPARED_HIGH_PAIR_POLICY=%q\n' "$B300_STAGER_HIGH_PAIR_POLICY"; printf 'B300_STAGER_PREPARED_HIGH_BLOCK_POLICY=%q\n' "$B300_STAGER_HIGH_BLOCK_POLICY"; printf 'B300_STAGER_PREPARED_HIGH_PAIR_L2_BYTES=%q\n' "$B300_STAGER_HIGH_PAIR_L2_BYTES"; printf 'B300_STAGER_PREPARED_HIGH_BLOCK_L2_BYTES=%q\n' "$B300_STAGER_HIGH_BLOCK_L2_BYTES"
    printf 'B300_STAGER_PREPARED_PAIR_POLICY=%q\n' "$B300_STAGER_PAIR_POLICY"; printf 'B300_STAGER_PREPARED_BLOCK_POLICY=%q\n' "$B300_STAGER_BLOCK_POLICY"; printf 'B300_STAGER_PREPARED_BIN=%q\n' "$B300_STAGER_FINAL_BIN"; printf 'B300_STAGER_PREPARED_LABEL=%q\n' "$label"; printf 'B300_STAGER_PREPARED_THREADS=%q\n' "$B300_STAGER_FINAL_THREADS"; printf 'B300_STAGER_PREPARED_CONTROL_BIN=%q\n' "$B300_STAGER_CONTROL_BIN"; printf 'B300_STAGER_PREPARED_CONTROL_LABEL=%q\n' "$control_label"; printf 'B300_STAGER_PREPARED_CONTROL_THREADS=%q\n' "$B300_STAGER_CONTROL_THREADS"; printf 'B300_STAGER_PREPARED_STAGED_SPEEDUP=%q\n' "$B300_STAGER_FINAL_SPEEDUP"; printf 'B300_STAGER_PREPARED_FINAL_STAGE_ROWS=%q\n' "$B300_STAGER_FINAL_STAGE_ROWS"; printf 'B300_STAGER_PREPARED_FINAL_STAGE_RESIDUE=%q\n' "$B300_STAGER_FINAL_STAGE_RESIDUE"; printf 'B300_STAGER_PREPARED_UPSTREAM_MANIFEST=%q\n' "$UP_MAN"; printf 'B300_STAGER_PREPARED_MANIFEST=%q\n' "$MANIFEST"; printf 'B300_STAGER_PREPARED_MANIFEST_SHA256=%q\n' "$MANIFEST_SHA"; printf 'B300_STAGER_PREPARED_PROMOTION_ENV=%q\n' "$PROMOTION_ENV"
  } >"$PREPARE_ENV"; cat "$PREPARE_ENV"; echo "STAGE R PREPARED upstream=$B300_STAGER_UPSTREAM_KIND low_pair=$B300_STAGER_PAIR_POLICY low_block=$B300_STAGER_BLOCK_POLICY speedup=${B300_STAGER_FINAL_SPEEDUP}x" >&2; exit 0
fi
[[ "$NGPU" == 8 ]] || { echo 'Stage-R complete-prime promotion requires NGPU=8; use PREPARE_ONLY=1 for screening' >&2; exit 2; }
exec env PROFILE_FILE="$PROFILE_FILE" ARCH="$ARCH" SMOKE_PRIME="$MOD" MAX_WINDOW="$MAX_WINDOW" FORCED_TARGET_MIB="$TARGET_MIB" FORCED_OVERRIDE_BIN="$B300_STAGER_FINAL_BIN" FORCED_OVERRIDE_LABEL="$label" FORCED_OVERRIDE_THREADS="$B300_STAGER_FINAL_THREADS" FORCED_BASE_BIN="$B300_STAGER_CONTROL_BIN" FORCED_BASE_LABEL="$control_label" FORCED_BASE_THREADS="$B300_STAGER_CONTROL_THREADS" REBUILD_BUCKETS="$REBUILD_BUCKETS" SELECT_ONLY="$SELECT_ONLY" RACE_PREFIX="$RACE_PREFIX" bash "$ONEESAN_ROOT/scripts/run/b300x8-race-external-forced-profiled-once.sh" 27 "$@"
